-- Recovered from the production Supabase migration ledger for L0 replay parity.
create table if not exists public.hq_workforce_correction_events(id uuid primary key default gen_random_uuid(),event_key text not null unique,decision_id uuid not null,decision_revision integer not null check(decision_revision>0),event_type text not null check(event_type in ('revise','reject','approve')),snapshot_id uuid references public.hq_context_decision_snapshots(id),run_id uuid references public.hq_workforce_runs(id),source_skill_id uuid references public.hq_workforce_skills(id),source_skill_version integer,worker_id uuid references public.hq_workforce_workers(id),lane_key text,context_hash text not null,proposed_payload jsonb not null default '{}'::jsonb,corrected_payload jsonb,rejection_reason text,structural_diff jsonb not null default '{}'::jsonb,provenance_bundle jsonb not null default '{}'::jsonb,learning_candidate_id uuid references public.hq_workforce_learning_candidates(id),created_at timestamptz not null default now(),unique(decision_id,decision_revision,source_skill_version,event_type));
create table if not exists public.hq_workforce_positive_evidence(id uuid primary key default gen_random_uuid(),evidence_key text not null unique,decision_id uuid not null,decision_revision integer not null,run_id uuid references public.hq_workforce_runs(id),skill_id uuid references public.hq_workforce_skills(id),snapshot_id uuid references public.hq_context_decision_snapshots(id),context_hash text not null,approved_payload jsonb not null default '{}'::jsonb,outcome_status text not null default 'pending',outcome_evidence jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(decision_id,decision_revision));
alter table public.hq_workforce_correction_events enable row level security; alter table public.hq_workforce_positive_evidence enable row level security;
create or replace function public.hq_workforce_capture_founder_decision(p_decision_id uuid,p_revision integer,p_event_type text,p_snapshot_id uuid,p_run_id uuid,p_proposed jsonb,p_corrected jsonb default null,p_rejection_reason text default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare r public.hq_workforce_runs%rowtype; sk public.hq_workforce_skills%rowtype; snap public.hq_context_decision_snapshots%rowtype; ekey text; chash text; diff jsonb:='{}'; cid uuid; eid uuid; existing public.hq_workforce_correction_events%rowtype; prov jsonb; begin if p_event_type not in ('revise','reject','approve') then raise exception 'Invalid founder event'; end if; if p_revision<1 then raise exception 'Revision must be >=1'; end if; select * into r from public.hq_workforce_runs where id=p_run_id; if not found then raise exception 'Run required'; end if; select * into sk from public.hq_workforce_skills where id=r.skill_id; select * into snap from public.hq_context_decision_snapshots where id=p_snapshot_id; if not found then raise exception 'Decision snapshot required'; end if; chash:=md5(jsonb_build_object('snapshot_id',snap.id,'facts',snap.facts,'rules_version',snap.rules_version,'context_version',snap.context_version)::text); ekey:=md5(p_decision_id::text||':'||p_revision||':'||coalesce(sk.version,0)||':'||p_event_type); if p_event_type='revise' then if p_corrected is null then raise exception 'Corrected payload required for revise'; end if; select coalesce(jsonb_object_agg(k,jsonb_build_object('proposed',p_proposed->k,'corrected',p_corrected->k)),'{}'::jsonb) into diff from (select key k from jsonb_object_keys(coalesce(p_proposed,'{}')) key union select key from jsonb_object_keys(coalesce(p_corrected,'{}')) key) q where p_proposed->k is distinct from p_corrected->k; elsif p_event_type='reject' then diff:=jsonb_build_object('counterexample',true,'reason',coalesce(p_rejection_reason,''),'auto_constraint',false); else insert into public.hq_workforce_positive_evidence(evidence_key,decision_id,decision_revision,run_id,skill_id,snapshot_id,context_hash,approved_payload) values(ekey,p_decision_id,p_revision,p_run_id,r.skill_id,p_snapshot_id,chash,coalesce(p_corrected,p_proposed,'{}')) on conflict(decision_id,decision_revision) do update set approved_payload=excluded.approved_payload returning id into eid; return jsonb_build_object('event_type','approve','candidate_created',false,'positive_evidence_id',eid,'context_hash',chash); end if; prov:=jsonb_build_object('snapshot_id',p_snapshot_id,'rules_version',snap.rules_version,'context_version',snap.context_version,'run_id',p_run_id,'worker_id',r.worker_id,'lane_key',r.lane_key,'source_skill_id',r.skill_id,'source_skill_key',sk.skill_key,'source_skill_version',sk.version,'context_hash',chash); select * into existing from public.hq_workforce_correction_events where event_key=ekey; if found then return jsonb_build_object('event_id',existing.id,'candidate_id',existing.learning_candidate_id,'deduplicated',true,'event_type',p_event_type); end if; insert into public.hq_workforce_learning_candidates(scope_type,scope_key,learning_type,statement,evidence_refs,confidence,confidence_source,status) values('skill',sk.skill_key,case when p_event_type='revise' then 'founder_revision' else 'founder_counterexample' end,case when p_event_type='revise' then 'Founder revision captured as structural evidence; qualification required before skill mutation.' else 'Founder rejection captured as contextual counterexample; no universal constraint may be inferred automatically.' end,array[ekey],1,'founder_explicit','candidate') returning id into cid; insert into public.hq_workforce_correction_events(event_key,decision_id,decision_revision,event_type,snapshot_id,run_id,source_skill_id,source_skill_version,worker_id,lane_key,context_hash,proposed_payload,corrected_payload,rejection_reason,structural_diff,provenance_bundle,learning_candidate_id) values(ekey,p_decision_id,p_revision,p_event_type,p_snapshot_id,p_run_id,r.skill_id,sk.version,r.worker_id,r.lane_key,chash,coalesce(p_proposed,'{}'),p_corrected,p_rejection_reason,diff,prov,cid) returning id into eid; return jsonb_build_object('event_id',eid,'candidate_id',cid,'deduplicated',false,'event_type',p_event_type,'context_hash',chash,'diff',diff); end $$;
revoke all on table public.hq_workforce_correction_events from anon,authenticated; revoke all on table public.hq_workforce_positive_evidence from anon,authenticated; revoke all on function public.hq_workforce_capture_founder_decision(uuid,integer,text,uuid,uuid,jsonb,jsonb,text) from public,anon,authenticated;
